/* Editorial experience: home 2/3, roots, project. Opening and workbench are not edited. */
(()=>{
const beforeHome=home,beforeBind=bindCineInteractions;
const pic=(src,alt,cls='')=>`<img src="assets/${src}" alt="${alt}" class="${cls}" loading="lazy" draggable="false">`;
const modal=`<dialog class="dn-dialog"><button class="dn-close" aria-label="关闭内容">关闭 ×</button><div class="dn-dialog-content"></div></dialog>`;
const credits=(kind)=>`<details class="dn-credits"><summary>照片与资料来源</summary><p>${kind==='home'?'枝头柿果：Salvador Escriva，CC BY-SA 4.0；苹果：Nasenfresse，公有领域；梨：JJ Harrison，CC BY-SA 2.5；整果色彩照片：Rodrigo.Argenton，CC BY-SA 4.0。':'红旗渠渠道与山谷：Gary Todd，CC0；虎口崖：eregli bob，CC BY-SA 3.0。柿果采收展示摄影：Angelo DeSantis，Fruit... persimmons (1944711898)，CC BY 2.0。'}图片按比例缩放与显示裁切，色彩互动是已注明的模拟。网络果实照片不是团队采集或等级标准样本。<a href="assets/photography-sources.html" target="_blank" rel="noopener">查看原始照片、作者与许可 ↗</a></p></details>`;
home=function(){let s=beforeHome(),a=s.indexOf('<section class="hf-orchard"'),b=s.indexOf('<section class="hf-season"');let intro=s.slice(0,a),season=s.slice(b);
season=season.replace('class="hf-season"','class="hf-season dn-season"').replace('几枚柿果。<br><em>一季秋色。</em>','看见色泽，<br><em>也看见差异。</em>').replace('保留真实的纹理与差异。<br>拖动观察色彩，移动光标放大细节。','拖动，感受色彩的细微变化。<br>靠近一点，看看果皮的真实纹理。').replace('放大柿果另一视角实拍','放大完整柿果实拍').replace('柿果另一拍摄视角','完整柿果真实摄影').replace('03 / 换个角度','03 / 整果细节').replace('拖动，留住这一刻的颜色','拖动，观察外观色彩');
return intro+`<section class="hf-orchard fx-orchard" id="collection" aria-labelledby="fx-title"><div class="hf-orchard-world" hidden></div><div class="hf-orchard-copy" hidden></div><div class="hf-targets" hidden></div><div class="hf-focus-note" hidden><button class="hf-return">返回</button><h3></h3><p></p></div><div class="fx-breath" aria-hidden="true"></div><div class="fx-heading"><span class="dn-eyebrow">山野未远，果实渐近</span><h2 id="fx-title">一方山水，<em>不止一种秋色。</em></h2><p>从柿果出发，把目光留给更多果实。</p></div><div class="fx-fruit-views" role="group" aria-label="选择果实观察主题"><button class="fx-fruit" data-fruit-view="0" aria-pressed="true"><div class="fx-photo dn-depth">${pic('orchard-real-branch.webp','枝头多枚完整柿果实拍')}</div><span><b>柿</b><small>当前研究 / 四级外观</small><i>01</i></span></button><button class="fx-fruit" data-fruit-view="1" aria-pressed="false"><div class="fx-photo dn-depth">${pic('apple-branch-real.webp','枝头完整苹果实拍')}</div><span><b>苹果</b><small>品类拓展 / 探索方向</small><i>02</i></span></button><button class="fx-fruit" data-fruit-view="2" aria-pressed="false"><div class="fx-photo dn-depth">${pic('pear-branch-real.webp','枝头三枚完整梨实拍')}</div><span><b>梨</b><small>品类拓展 / 探索方向</small><i>03</i></span></button></div><div class="fx-observation-line" aria-live="polite"><span id="fx-observation-label">柿果 / 看颜色，也看遮挡</span><p id="fx-observation-copy">当前以柿果四级外观分级为起点。下一屏可以拖动色谱，细看真实表皮纹理。</p><a href="#home/autumn-study">继续观察柿果 ↓</a></div>${credits('home')}</section>`+season.replace('aria-labelledby="hf-season-title"','id="autumn-study" aria-labelledby="hf-season-title"')+modal};
const canalScenes=[['canal-bend.webp','沿山的水路','渠道贴着岩壁延伸，水与山体构成清楚的空间关系。','Gary Todd / CC0'],['canal-valley.webp','山谷的尺度','从更开阔的视角，理解渠道所在的山地环境。','Gary Todd / CC0'],['canal-cliff.webp','崖壁之间','从实景照片中，近看渠墙、步道与崖壁。','eregli bob / CC BY-SA 3.0']];
roots=function(){return `<section class="dn-canal dn-page" aria-labelledby="dn-roots-title"><div class="dn-canal-heading"><div><span class="dn-eyebrow">山渠与产业 / LINZHOU</span><h1 id="dn-roots-title">山间一线水，<br><em>流向人间烟火。</em></h1></div><p>沿着真实的渠道，走近太行的土地。<br>看见山水，也看见生产与生活。</p></div><div class="dn-canal-view"><div class="dn-canal-image dn-depth">${pic('canal-bend.webp','红旗渠沿崖壁延伸的真实照片','dn-canal-active')}<span class="dn-canal-credit">Gary Todd / CC0</span></div><div class="dn-canal-selector"><span class="dn-eyebrow">沿渠看见 / 选择视角</span>${canalScenes.map((s,i)=>`<button data-canal-scene="${i}" aria-pressed="${i===0}"><span>0${i+1}</span><b>${s[1]}</b><i>↗</i></button>`).join('')}<p id="dn-canal-caption">${canalScenes[0][2]}</p><small>独立实景视角，非连续路线地图。</small></div></div><a class="dn-down" href="#roots/land">从山水，走向果实 ↓</a></section><section class="dn-land dn-page" id="land"><div class="dn-land-photo dn-depth">${pic('harvest-real.webp','多枚真实柿果采收展示摄影')}<span>采收展示摄影 / 非团队调研记录</span></div><div class="dn-land-copy"><span class="dn-eyebrow">把技术，落到具体问题里</span><h2>一枚果实背后，<br>是一季忙碌。</h2><p class="dn-lede">计划书把应用重点放在近景分选和手机拍照。<br>从实际操作出发，先把分级这一步做扎实。</p><div class="dn-questions">${['旺季，人手从哪里来？','同一批果，标准怎样统一？','工具，怎样融入现有流程？'].map((s,i)=>`<button data-question="${i}" aria-expanded="${i===0}"><span>0${i+1}</span>${s}<b>＋</b></button><div class="dn-answer" data-answer="${i}" ${i?'hidden':''}>${['合作社和加工主体在旺季面临逐果目测的用工压力。项目希望用固定摄像头采集与自动分级，探索减少重复判断的投入。','未熟、转色期、着色期、完熟四级外观标签，是项目统一讨论与标注的起点。内部品质和脱涩状态仍需其他依据。','固定摄像头用于稳定的分选台场景，手机拍照用于临时观察与抽检。实际降本与现场效果仍需要持续验证。'][i]}</div>`).join('')}</div><a class="dn-text-link" href="#about">查看项目的方法与依据 ↗</a></div>${credits('roots')}</section>${modal}`};
const workflow=[['采集输入','拍清楚，是第一步。','手机拍照与固定摄像头是计划书中的两种采集方式。当前网页支持本地上传与查看。','01 / INPUT'],['检测定位','先找到每一枚果实。','YOLO11n 负责定位图像中的果实。近景分选是当前主要场景，整树远景小目标仍是改进重点。','02 / DETECT'],['逐果分级','再读懂每一枚的外观。','YOLO11n-cls 对检测到的果实逐一分类，区分四种外观等级。颜色特征是重要线索。','03 / CLASSIFY'],['结果汇总','让结果对应到目标。','项目方案汇总逐果标签与各级数量。当前展示网页尚未连接推理服务，真实结果须由模型返回。','04 / RESULT']];
const dossiers=[['分级依据','先统一“怎么看”。','计划书依据果面色泽建立四级标签：未熟、转色期、着色期、完熟。四类平均色相记录为 62.7°、53.2°、35.6°、29.5°，仅代表该批数据统计，不是通用品种阈值。',null,'04','外观等级'],['数据与采集','每张图像，都有来处。','计划书记录成熟度分类集 443 张，训练 353 张、验证 90 张；检测集 108 张，训练 92 张、验证 16 张。采用分层划分与重复校验，目前尚无独立测试集。文档记载产区调研与 105 张果园照片采集，原始样本尚未在本站公开展示。',null,'443','分类图像'],['实验与边界','看结果，也看薄弱处。','计划书验证集记录：分类 top-1 88.89%（80/90）；检测 mAP@0.5 90.87%，两者属于不同任务。转色期召回率 73.68%，整树远景小目标仍有漏检。下图来自计划书原有实验材料。','project-recall.webp','88.89%','分类验证 top-1'],['参数适配','让训练尊重颜色。','计划书记录调低色相与饱和度扰动、关闭自动增强后，着色期召回率由 64% 提至 88%，整体 top-1 由 84.44% 提至 88.89%。下图为计划书原有对比图。','project-adaptation.webp','+24','百分点 / 着色期召回']];
about=function(){return `<section class="dn-project dn-page"><div class="dn-project-top"><div><span class="dn-eyebrow">太行智农 / 项目与验证</span><h1>让每一枚果实，<br><em>有据可分。</em></h1></div><div class="dn-project-description"><p>面向近景分选与采收的<br>柿果成熟度智能分级探索。</p><span>两级模型 · 本地部署方案 · 四级外观标签</span></div></div><div class="dn-system"><div class="dn-system-header"><span>一张照片，走过四个环节</span><span>可点选的技术路径 / 非实时推理</span></div><div class="dn-flow">${workflow.map((s,i)=>`<button data-workflow="${i}" aria-pressed="${i===0}"><span>0${i+1}</span><div class="dn-flow-icon dn-icon-${i}" aria-hidden="true">${i===0?'<i></i>':i===1?'<i></i><i></i><i></i>':i===2?'<i></i><i></i><i></i><i></i>':'<i></i><i></i><i></i><i></i>'}</div><b>${s[0]}</b><small>${['手机 / 摄像头','YOLO11n','YOLO11n-cls','标签 / 数量'][i]}</small></button>`).join('')}</div><div class="dn-workflow-detail" aria-live="polite"><span id="dn-workflow-index">01 / INPUT</span><div><h3 id="dn-workflow-title"></h3><p id="dn-workflow-copy"></p></div><button id="dn-next-step" class="dn-next">下一环节 →</button></div></div><div class="dn-evidence-strip"><div><b>443</b><span>分类图像 / 353 训练 + 90 验证</span></div><div><b>88.89<small>%</small></b><span>分类验证 top-1 / 80/90</span></div><div><b>8.27<small>MB</small></b><span>两层模型合计 / 计划书记录</span></div><a href="#about/records">打开验证档案 ↓</a></div><small class="dn-project-boundary">以上来自项目计划书，非独立测试或生产效果指标；当前展示网站尚未接入项目推理服务。</small></section><section class="dn-records dn-page" id="records"><div class="dn-records-heading"><span class="dn-eyebrow">THE WORKING ARCHIVE</span><h2>把依据，<em>展开来看。</em></h2><p>项目的进步、限制与下一步，都留在这里。</p></div><div class="dn-reading-desk"><div class="dn-record-tabs" role="group" aria-label="选择项目档案">${dossiers.map((d,i)=>`<button data-record="${i}" aria-pressed="${i===0}"><span>0${i+1}</span><b>${d[0]}</b><i>↗</i></button>`).join('')}<p>资料来源<br>《太行智农项目计划书》<br>2026 年 10 月</p></div><article class="dn-record-preview"><div id="dn-record-media"></div><div class="dn-record-copy"><span id="dn-record-label"></span><h3 id="dn-record-title"></h3><p id="dn-record-copy"></p><button id="dn-open-record" class="dn-text-link">阅读档案说明 ↗</button></div></article></div></section>${modal}`};
bindCineInteractions=function(){
if(route==='recognize'){beforeBind();return}const root=document.getElementById('app'),dlg=root.querySelector('.dn-dialog');const open=(content)=>{dlg.querySelector('.dn-dialog-content').innerHTML=content;dlg.showModal()};if(dlg){dlg.querySelector('.dn-close').onclick=()=>dlg.close();dlg.onclick=e=>{if(e.target===dlg)dlg.close()}}const reduce=matchMedia('(prefers-reduced-motion:reduce)').matches;
function depth(){if(reduce||!matchMedia('(pointer:fine)').matches)return;root.querySelectorAll('.dn-depth').forEach(el=>{el.onpointermove=e=>{let r=el.getBoundingClientRect();el.style.setProperty('--dx',((e.clientX-r.left)/r.width-.5)*8+'px');el.style.setProperty('--dy',((e.clientY-r.top)/r.height-.5)*6+'px');el.style.setProperty('--cursor-x',(e.clientX-r.left)+'px');el.style.setProperty('--cursor-y',(e.clientY-r.top)+'px')};el.onpointerleave=()=>{el.style.setProperty('--dx','0px');el.style.setProperty('--dy','0px')}})}
if(route==='home'){
beforeBind();root.querySelector('.hf-orchard').onpointermove=null;root.querySelector('.hf-orchard').onpointerleave=null;
const oldCredits=root.querySelector('.rp-credits');if(oldCredits)oldCredits.outerHTML=credits('home');
const fruitNotes=[['柿果 / 看颜色，也看遮挡','当前以柿果四级外观分级为起点。下一屏可以拖动色谱，细看真实表皮纹理。'],['苹果 / 留意底色、反光与轮廓','苹果作为后续拓展方向展示。不同品种不能套用柿果的颜色分级，当前不表示已具备苹果成熟度检测。'],['梨 / 留意果皮纹理与拍摄光线','梨作为后续拓展方向展示。照片适合用来学习清晰采集，不能凭外观推断糖度；当前不表示已具备梨成熟度检测。']];root.querySelectorAll('[data-fruit-view]').forEach(b=>b.onclick=()=>{const i=+b.dataset.fruitView;root.querySelectorAll('[data-fruit-view]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));root.querySelector('#fx-observation-label').textContent=fruitNotes[i][0];root.querySelector('#fx-observation-copy').textContent=fruitNotes[i][1]});
depth();return;
}
if(route==='roots'){
let current=0,ticket=0;const image=root.querySelector('.dn-canal-active');root.querySelectorAll('[data-canal-scene]').forEach(b=>b.onclick=async()=>{let i=+b.dataset.canalScene,version=++ticket,d=canalScenes[i];const next=new Image();next.src='assets/'+d[0];try{await next.decode()}catch{return}if(ticket!==version||!image.isConnected)return;current=i;image.src=next.src;image.alt=d[1]+' / 红旗渠实景';root.querySelector('.dn-canal-credit').textContent=d[3];root.querySelector('#dn-canal-caption').textContent=d[2];root.querySelectorAll('[data-canal-scene]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));image.animate?.([{opacity:.65},{opacity:1}],{duration:reduce?0:550})});const canalExpand=root.querySelector('#dn-canal-expand');if(canalExpand)canalExpand.onclick=()=>{let d=canalScenes[current];open(`<span class="dn-eyebrow">林州 / 红旗渠实景</span><h2>${d[1]}</h2>${pic(d[0],d[1])}<p>${d[2]}</p><small>${d[3]}</small>`)};
root.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>{let i=+b.dataset.question;root.querySelectorAll('[data-question]').forEach(x=>x.setAttribute('aria-expanded',String(x===b)));root.querySelectorAll('[data-answer]').forEach(x=>x.hidden=+x.dataset.answer!==i)});depth();return;
}
if(route==='about'){
let step=0,record=0;function showStep(i){step=i;const d=workflow[i];root.querySelectorAll('[data-workflow]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.workflow===i)));root.querySelector('#dn-workflow-index').textContent=d[3];root.querySelector('#dn-workflow-title').textContent=d[1];root.querySelector('#dn-workflow-copy').textContent=d[2];root.querySelector('.dn-system').style.setProperty('--step',i)}root.querySelectorAll('[data-workflow]').forEach(b=>b.onclick=()=>showStep(+b.dataset.workflow));root.querySelector('#dn-next-step').onclick=()=>showStep((step+1)%4);showStep(0);
function showRecord(i){record=i;let d=dossiers[i];root.querySelectorAll('[data-record]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.record===i)));root.querySelector('#dn-record-media').innerHTML=d[3]?pic(d[3],d[0]+' / 计划书原有图表'):`<div class="dn-archive-number"><b>${d[4]}</b><span>${d[5]}</span>${i===0?'<div class="dn-grade-dots"><i></i><i></i><i></i><i></i></div>':'<div class="dn-data-split"><i></i><span>353 训练 / 90 验证</span></div>'}</div>`;root.querySelector('#dn-record-label').textContent='0'+(i+1)+' / '+d[0];root.querySelector('#dn-record-title').textContent=d[1];root.querySelector('#dn-record-copy').textContent=d[2]};root.querySelectorAll('[data-record]').forEach(b=>b.onclick=()=>showRecord(+b.dataset.record));root.querySelector('#dn-open-record').onclick=()=>{let d=dossiers[record];open(`<span class="dn-eyebrow">项目档案 / ${d[0]}</span><h2>${d[1]}</h2><p>${d[2]}</p><small>来源：项目计划书 / 验证集记录，独立测试集待补充。</small>`)};showRecord(0);
}
};
})();
